from html.parser import HTMLParser
class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ('br','hr','img','input','meta','link','area','base','col','embed','source','track','wbr','param'):
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag not in ('br','hr','img','input','meta','link','area','base','col','embed','source','track','wbr','param'):
            if self.stack and self.stack[-1] == tag:
                self.stack.pop()
            elif self.stack:
                self.errors.append(f'Mismatched: expected {self.stack[-1]}, got {tag}')
with open('/app/output/final_report.html') as f:
    c = Checker()
    c.feed(f.read())
print(f'Unclosed tags: {c.stack}')
print(f'Errors: {c.errors}')
print('HTML structure valid!' if not c.errors and not c.stack else 'ISSUES FOUND')
"

